settings.custom_css:
#wonderment-pdp-eta {
margin-top: 25px;
margin-bottom: 25px;
}
@media screen and (min-width:768px) {
#wonderment-pdp-eta {
margin-top: 0px;
margin-bottom: 30px;
}
}

settings.custom_liquid:
{%- assign imgs = product.metafields.custom.end_of_watch_family_and_friends_images.value -%}
{%- if imgs != blank -%}
<div class="page-width gs-metafield-grid">
  {%- if "FAMILY AND FRIENDS OF THE FALLEN" != blank -%}<h2 class="gs-metafield-grid__heading"><strong>FAMILY AND FRIENDS OF THE FALLEN</strong></h2>{%- endif -%}
  <div class="gs-metafield-grid__items">
    {%- for img in imgs -%}
      {{ img | image_url: width: 600 | image_tag: loading: 'lazy', class: 'gs-metafield-grid__img' }}
    {%- endfor -%}
  </div>
</div>
<style>
  .gs-metafield-grid__heading { text-align: center; margin: 0 0 2rem; }
  .gs-metafield-grid__items { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
  .gs-metafield-grid__img { display: block; width: 100%; height: auto; aspect-ratio: 1; object-fit: cover; }
  @media screen and (min-width: 750px) { .gs-metafield-grid__items { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 20px; } }
</style>
{%- endif -%}
